-- Manager Library — schema `library` (docs/spec-laravel-react/data-model.md).
-- No column DEFAULTs: identifiers and instants are generated by the application (constitution Article VII).
-- All statements are idempotent so the migration can be re-run safely.

CREATE SCHEMA IF NOT EXISTS library;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS library.category (
    id   uuid         NOT NULL,
    name varchar(120) NOT NULL,
    CONSTRAINT pk_category PRIMARY KEY (id),
    CONSTRAINT uq_category_name UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS library."user" (
    id            uuid         NOT NULL,
    username      varchar(120) NOT NULL,
    password_hash varchar(512) NOT NULL,
    role          varchar(40)  NOT NULL,
    CONSTRAINT pk_user PRIMARY KEY (id),
    CONSTRAINT uq_user_username UNIQUE (username),
    CONSTRAINT ck_user_role CHECK (role IN ('admin', 'librarian'))
);

CREATE TABLE IF NOT EXISTS library.member (
    id              uuid         NOT NULL,
    full_name       varchar(200) NOT NULL,
    document_number varchar(30)  NOT NULL,
    CONSTRAINT pk_member PRIMARY KEY (id),
    CONSTRAINT uq_member_document UNIQUE (document_number)
);

CREATE TABLE IF NOT EXISTS library.book (
    id               uuid         NOT NULL,
    title            varchar(250) NOT NULL,
    author           varchar(200) NOT NULL,
    isbn             char(13)     NOT NULL,
    category_id      uuid         NOT NULL,
    total_copies     integer      NOT NULL,
    available_copies integer      NOT NULL,
    cover_key        varchar(512) NULL,
    deleted_at       timestamptz  NULL,
    CONSTRAINT pk_book PRIMARY KEY (id),
    CONSTRAINT fk_book_category FOREIGN KEY (category_id) REFERENCES library.category (id) ON DELETE RESTRICT,
    CONSTRAINT ck_book_total_positive CHECK (total_copies >= 1),
    CONSTRAINT ck_book_available_range CHECK (available_copies >= 0 AND available_copies <= total_copies)
);

CREATE TABLE IF NOT EXISTS library.loan (
    id                uuid        NOT NULL,
    member_id         uuid        NOT NULL,
    loaned_by_user_id uuid        NOT NULL,
    loaned_at         timestamptz NOT NULL,
    CONSTRAINT pk_loan PRIMARY KEY (id),
    CONSTRAINT fk_loan_member FOREIGN KEY (member_id) REFERENCES library.member (id) ON DELETE RESTRICT,
    CONSTRAINT fk_loan_user FOREIGN KEY (loaned_by_user_id) REFERENCES library."user" (id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS library.loan_item (
    id            uuid         NOT NULL,
    loan_id       uuid         NOT NULL,
    book_id       uuid         NOT NULL,
    book_title    varchar(250) NOT NULL,
    isbn          char(13)     NOT NULL,
    category_name varchar(120) NOT NULL,
    due_at        timestamptz  NOT NULL,
    returned_at   timestamptz  NULL,
    CONSTRAINT pk_loan_item PRIMARY KEY (id),
    CONSTRAINT fk_loan_item_loan FOREIGN KEY (loan_id) REFERENCES library.loan (id) ON DELETE CASCADE,
    CONSTRAINT fk_loan_item_book FOREIGN KEY (book_id) REFERENCES library.book (id) ON DELETE RESTRICT,
    CONSTRAINT uq_loan_item_loan_book UNIQUE (loan_id, book_id)
);

-- Unique ISBN among ACTIVE books only (ADR-003).
CREATE UNIQUE INDEX IF NOT EXISTS ux_book_isbn_active ON library.book (isbn) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS ix_book_category ON library.book (category_id);
CREATE INDEX IF NOT EXISTS ix_book_title_trgm ON library.book USING gin (title gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_book_author_trgm ON library.book USING gin (author gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_member_name_trgm ON library.member USING gin (full_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_member_document_trgm ON library.member USING gin (document_number gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_loan_loaned_at ON library.loan (loaned_at);
CREATE INDEX IF NOT EXISTS ix_loan_member ON library.loan (member_id);
CREATE INDEX IF NOT EXISTS ix_loan_item_book ON library.loan_item (book_id);
CREATE INDEX IF NOT EXISTS ix_loan_item_unreturned ON library.loan_item (due_at) WHERE returned_at IS NULL;

-- Fixed categories (data-model §9). Fixed identifiers so every environment agrees.
